// MarketingServer is the server API for Marketing service.
// All implementations must embed UnimplementedMarketingServer
// for forward compatibility
type MarketingServer interface {
	// QuoteCheckout 报价试算：券/积分抵扣/活动宝箱资格全抵计算 + 落 OPEN 报价锁（幂等 uk request_id：撞键读回原报价）
	QuoteCheckout(context.Context, *QuoteCheckoutReq) (*QuoteCheckoutResp, error)
	// LockQuote SAGA 03 正向：quote OPEN→LOCKED、券/资格 AVAILABLE→LOCKED（barrier + FOR UPDATE）
	LockQuote(context.Context, *LockQuoteReq) (*LockQuoteResp, error)
	// ReleaseQuote SAGA 03 补偿：quote LOCKED→RELEASED、券/资格 LOCKED→AVAILABLE（USED 不回退）
	ReleaseQuote(context.Context, *ReleaseQuoteReq) (*ReleaseQuoteResp, error)
	// CommitQuote SAGA 07 sub-call：quote LOCKED→USED（幂等）
	CommitQuote(context.Context, *CommitQuoteReq) (*CommitQuoteResp, error)
	// ── 玩法域跨服务只读（play-rpc 拆分后经 RPC 读报价/券模板，不直连营销库）──
	// GetQuote 读报价状态与锁定信息（玩法 lock 校验/readback/memorymatch 实付展示）
	GetQuote(context.Context, *GetQuoteReq) (*GetQuoteResp, error)
	// GetCouponTemplateByNo 按模板单号查券模板（玩法发奖展示券名；NotFound 调用方静默降级）
	GetCouponTemplateByNo(context.Context, *GetCouponTemplateByNoReq) (*CouponTemplateItem, error)
	// GrantPlayCoupon 玩法结算发券：coupon_no="uc_"+requestId 幂等（撞键读回原券）
	GrantPlayCoupon(context.Context, *GrantPlayCouponReq) (*GrantPlayCouponResp, error)
	// ClaimCoupon 领取券：coupon_no="uc_"+claimRequestId 确定性派生，幂等
	ClaimCoupon(context.Context, *ClaimCouponReq) (*ClaimCouponResp, error)
	// ListUserCoupons 我的券列表（含模板信息）
	ListUserCoupons(context.Context, *ListUserCouponsReq) (*ListUserCouponsResp, error)
	// ListCouponTemplates 券模板列表（领取页；claimed=该用户是否已领过）
	ListCouponTemplates(context.Context, *ListCouponTemplatesReq) (*ListCouponTemplatesResp, error)
	// ── M14d 控制台：券模板不可变版本/发券/忠诚度默认值（消息形状照抄 server_v2 promotion）──
	PublishCouponTemplate(context.Context, *PublishCouponTemplateRequest) (*CouponTemplate, error)
	GetCouponTemplate(context.Context, *GetCouponTemplateRequest) (*CouponTemplate, error)
	ListCouponTemplateVersions(context.Context, *ListCouponTemplateVersionsRequest) (*ListCouponTemplateVersionsReply, error)
	// ── M14d 券池（券池记录与券模板分离）──
	// ListCouponPoolEntries 券池列表（关联最新券模板名称）
	ListCouponPoolEntries(context.Context, *ListCouponPoolEntriesRequest) (*ListCouponPoolEntriesReply, error)
	// GetCouponPoolEntry 查看券池记录
	GetCouponPoolEntry(context.Context, *GetCouponPoolEntryRequest) (*CouponPoolEntry, error)
	// UpsertCouponPoolEntry 创建/编辑券池记录（id=0 创建，id>0 编辑）
	UpsertCouponPoolEntry(context.Context, *UpsertCouponPoolEntryRequest) (*CouponPoolEntry, error)
	// AdjustCouponPoolEntry 管理员增加/减少券池库存（写流水）
	AdjustCouponPoolEntry(context.Context, *AdjustCouponPoolEntryRequest) (*CouponPoolEntry, error)
	// ListCouponLedger 券池/用户券变动流水
	ListCouponLedger(context.Context, *ListCouponLedgerRequest) (*ListCouponLedgerReply, error)
	// ── 吉祥值奖励配置 ──
	ListFortuneRewards(context.Context, *ListFortuneRewardsRequest) (*ListFortuneRewardsReply, error)
	GetFortuneReward(context.Context, *GetFortuneRewardRequest) (*FortuneReward, error)
	UpsertFortuneReward(context.Context, *UpsertFortuneRewardRequest) (*FortuneReward, error)
	// ── 活动列表 ──
	ListActivities(context.Context, *ListActivitiesRequest) (*ListActivitiesReply, error)
	GetActivity(context.Context, *GetActivityRequest) (*Activity, error)
	UpsertActivity(context.Context, *UpsertActivityRequest) (*Activity, error)
	// ── 公告列表 ──
	ListAnnouncements(context.Context, *ListAnnouncementsRequest) (*ListAnnouncementsReply, error)
	GetAnnouncement(context.Context, *GetAnnouncementRequest) (*Announcement, error)
	UpsertAnnouncement(context.Context, *UpsertAnnouncementRequest) (*Announcement, error)
	// ── Banner 列表 ──
	ListBanners(context.Context, *ListBannersRequest) (*ListBannersReply, error)
	GetBanner(context.Context, *GetBannerRequest) (*Banner, error)
	UpsertBanner(context.Context, *UpsertBannerRequest) (*Banner, error)
	GrantCoupons(context.Context, *GrantCouponsRequest) (*GrantCouponsReply, error)
	GetTenantLoyaltyDefaults(context.Context, *GetTenantLoyaltyDefaultsRequest) (*TenantLoyaltyDefaults, error)
	PutTenantLoyaltyDefaults(context.Context, *PutTenantLoyaltyDefaultsRequest) (*TenantLoyaltyDefaults, error)
	// ── M11 campaign 活动域 ──
	// ListCampaigns 活动列表 + 我的状态
	ListCampaigns(context.Context, *ListCampaignsReq) (*ListCampaignsResp, error)
	// CampaignPreview 参与预览（kind 分发，无写入）
	CampaignPreview(context.Context, *CampaignPreviewReq) (*CampaignPreviewResp, error)
	// CampaignParticipate 统一参与入口（kind 分发 + idem_key 幂等重放 + PENDING 补发）
	CampaignParticipate(context.Context, *CampaignParticipateReq) (*CampaignParticipateResp, error)
	// ---- 活动宝箱资格 ----
	ListCampaignBoxEntitlements(context.Context, *ListCampaignBoxEntitlementsReq) (*ListCampaignBoxEntitlementsResp, error)
	GetCampaignBoxEntitlement(context.Context, *GetCampaignBoxEntitlementReq) (*GetCampaignBoxEntitlementResp, error)
	// ── M14d 控制台：活动版本化（消息形状照抄 server_v2 campaign）──
	CreateCampaignDraft(context.Context, *CreateCampaignDraftRequest) (*Campaign, error)
	PublishCampaign(context.Context, *PublishCampaignRequest) (*Campaign, error)
	GetCampaign(context.Context, *GetCampaignRequest) (*Campaign, error)
	mustEmbedUnimplementedMarketingServer()
}

